module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4'b0000 = S0, 4'b0001 = S1, 4'b0010 = S2, 4'b0011 = S3
    reg [3:0] state, next_state;

    // State register (synchronous reset, active-high)
    always @(posedge clk) begin
        if (reset)
            state <= 4'b0000;  // S0
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always @(*) begin
        case (state)
            4'b0000: begin // State S0
                if (data == 1'b1)
                    next_state = 4'b0001; // S0 --data=1--> S1
                else
                    next_state = 4'b0000; // S0 --data=0--> S0
            end
            4'b0001: begin // State S1
                if (data == 1'b1)
                    next_state = 4'b0010; // S1 --data=1--> S2
                else
                    next_state = 4'b0000; // S1 --data=0--> S0
            end
            4'b0010: begin // State S2
                if (data == 1'b1)
                    next_state = 4'b0011; // S2 --data=1--> S3
                else
                    next_state = 4'b0000; // S2 --data=0--> S0
            end
            4'b0011: begin // State S3
                if (data == 1'b1)
                    next_state = 4'b0001; // S3 --data=1--> S1 (overlap: last '1' of 1101)
                else
                    next_state = 4'b0000; // S3 --data=0--> S0
            end
            default: next_state = 4'b0000;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    // start_shifting is 1 when the sequence 1101 is fully detected (in state S3)
    assign start_shifting = (state == 4'b0011) ? 1'b1 : 1'b0;

endmodule

