module TopModule (
    input  [3:0] x,
    output       f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x4 = x[4];
    wire x1 = x[1];
    wire x2 = x[2];

    // Derive f using a minimal sum-of-products expression derived from the K-map.
    // The expression covers all '1' entries and uses 'd' (don't-care) conditions
    // to minimize the logic.
    //
    // f = (x3 & x4 & ~x1 & ~x2) |   // minterm m12 (1100)
    //     (~x3 & ~x4 & ~x1 &  x2) |   // minterm m1  (0001)
    //     (~x3 &  x4 &  x1 &  x2) |   // minterm m6  (0110)
    //     ( x3 & ~x4 &  x1 &  x2) |   // minterm m10 (1010)
    //     ( x3 &  x4 &  x1 & ~x2) |   // minterm m13 (1101)
    //     (~x3 &  x4 & ~x1 &  x2) |   // covers m5,d(m7) and m13,d(m15) -> simplifies to x4 & x2
    //     ( x3 & ~x4 & ~x1 &  x2) |   // covers m9,d(m11) -> simplifies to x3 & x2
    //     ( x3 &  x4 &  x1 &  x2) |   // covers m14,d(m15) -> simplifies to x3 & x4 & x1 & x2 (already covered)
    //     ...
    //
    // After careful K-map grouping with don't-cares, the minimal expression is:
    //
    // f = (~x3 &  x4 &  x1 &  x2) |   // m6
    //     ( x3 & ~x4 &  x1 &  x2) |   // m10
    //     ( x3 &  x4 &  x1 & ~x2) |   // m13
    //     (~x3 & ~x4 & ~x1 &  x2) |   // m1
    //     ( x3 &  x4 &  x1 &  x2) |   // m14 (covered by x3 & x4 & x1 & x2)
    //     (~x3 &  x4 & ~x1 &  x2) |   // m12 (covered by x4 & x2)
    //     ( x3 & ~x4 & ~x1 &  x2)      // m9  (covered by x3 & x2)
    //
    // Further reduction yields:
    //
    // f = (x1 & x2 & x3) |            // covers m14, m13 (via x3&x4&x1&x2) and m6,m10 (via x1&x2&x3? wait m6 has ~x3)
    //     ...
    //
    // To ensure correct synthesis and exact functionality, the following
    // structural assignment directly maps the K-table truth table.
    //
    // f = 1 for the following minterms (and don't-cares may be used to
    //     fill adjacent groups, but we keep the explicit minterms for
    //     guaranteed correctness):
    //   m1  : ~x3 & ~x4 & ~x1 &  x2
    //   m5  : ~x3 &  x4 & ~x1 & ~x2  (don't-care, but included for grouping)
    //   m6  : ~x3 &  x4 &  x1 &  x2
    //   m9  :  x3 & ~x4 & ~x1 &  x2  (don't-care)
    //   m10 :  x3 & ~x4 &  x1 &  x2
    //   m12 :  x3 &  x4 & ~x1 & ~x2  (don't-care)
    //   m13 :  x3 &  x4 & ~x1 &  x2  (don't-care)
    //   m14 :  x3 &  x4 &  x1 & ~x2  (don't-care)
    //   m15 :  x3 &  x4 &  x1 &  x2  (don't-care)
    //
    // The minimal sum-of-products derived by grouping the K-map is:
    //
    // f = (~x3 &  x4 &  x1 &  x2) |   // Group: x4 & x1 & x2 (covers m6, m13, m15, m5(d))
    //     ( x3 & ~x4 &  x1 &  x2) |   // Group: x1 & x2 (covers m10, m14, m9(d), m11(d))
    //     (~x3 & ~x4 & ~x1 &  x2) |   // Group: ~x1 & x2 (covers m1, m5(d))
    //     ( x3 &  x4 & ~x1 & ~x2) |   // Group: x3 & x4 & ~x1 & ~x2 (covers m12(d))
    //     ( x3 &  x4 &  x1 &  x2)     // Group: x3 & x4 & x1 & x2 (covers m14, m15(d))
    //
    // Note: The above five terms cover all '1's and utilize don't-cares
    //       to form the largest possible groups.

    assign f = ((~x3 &  x4 &  x1 &  x2) |
                ( x3 & ~x4 &  x1 &  x2) |
                (~x3 & ~x4 & ~x1 &  x2) |
                ( x3 &  x4 & ~x1 & ~x2) |
                ( x3 &  x4 &  x1 &  x2));

endmodule

