module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding:
    // 3 bits for state type
    // 1 bit for walking direction (when walking or falling)
    // 5 bits for fall/dig counter (0-31, >20 splatter)
    typedef enum logic [7:0] {
        // {type[2:1], dir, cnt[4:0]}
        // type: 0=WALK_LEFT, 1=WALK_RIGHT, 2=DIGGING, 3=FALLING, 4=SPLATTERED
        // dir:  0=left, 1=right (valid when type in {0,1,3})

        ST_WALK_LEFT   = 8'b00_00_00000, // type=00, dir=0, cnt=0
        ST_WALK_RIGHT  = 8'b00_01_00000, // type=00, dir=1, cnt=0
        ST_DIGGING     = 8'b00_10_00000, // type=01, dir=0 (ignored, only ground matters)
        ST_FALLING     = 8'b01_00_00000, // type=01, dir=0 (dir bit repurposed as fall counter bit 4)
        ST_SPLATTERED  = 8'b10_00_00000  // type=10, dir=0, cnt=0
    } state_enc_t;

    logic [7:0] state, next_state;

    // Output decode (Moore: outputs depend only on current state)
    assign walk_left   = (state == ST_WALK_LEFT);
    assign walk_right  = (state == ST_WALK_RIGHT);
    assign aaah        = (state[7:6] == 2'b01); // type=01 (FALLING)
    assign digging     = (state == ST_DIGGING);

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= ST_WALK_LEFT;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        next_state = state;
        logic [1:0] type = state[7:6];
        logic       dir  = state[5];    // 0=left, 1=right (when type in {0,1,3})
        logic [4:0] cnt  = state[4:0]; // fall counter (0-31)

        // Pre-compute new counter (increment every cycle while not splattered)
        logic [4:0] new_cnt = cnt + 1'b1;
        // Clamp at 31 (splatter threshold 20+)
        if (new_cnt == 5'd31) new_cnt = 5'd31;

        case (type)
            2'b00: begin // Walking states (LEFT or RIGHT)
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fell: transition to FALLING, preserve direction
                    next_state = {ST_FALLING, dir, cnt}; // cnt will be overwritten below but preserved for now
                end else if (dig) begin
                    // Start digging (only valid when on ground and not already falling)
                    next_state = {ST_DIGGING, dir, 5'd0};
                end else if (bump_left) begin
                    // Bumped on left -> walk right
                    next_state = {ST_WALK_RIGHT, 1'b1, 5'd0};
                end else if (bump_right) begin
                    // Bumped on right -> walk left
                    next_state = {ST_WALK_LEFT, 1'b0, 5'd0};
                end
                // else stay in current walking state
            end

            2'b01: begin // FALLING state
                if (ground) begin
                    // Ground hit: check fall count
                    if (new_cnt > 20) begin
                        // Splatter: forever stuck
                        next_state = ST_SPLATTERED;
                    end else begin
                        // Resume walking in same direction
                        next_state = {ST_WALK_LEFT, dir, new_cnt}; // dir preserved, cnt=0 (will be 0 due to encoding)
                        // Actually need cnt=0 for walking state, so force it:
                        next_state = (dir == 1'b1) ? ST_WALK_RIGHT : ST_WALK_LEFT;
                    end
                end
                // else stay falling (counter keeps incrementing)
            end

            2'b10: begin // SPLATTERED state
                // Forever stuck, no transitions (already assigned default)
            end

            default: next_state = ST_WALK_LEFT; // Should never happen
        endcase
    end

endmodule

