module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,   // 10-bit one-hot state input as per specification
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot state encoding as specified:
    // (S, S1, S11, S110, B0, B1, B2, B3, Count, Wait)
    // = (10'b0000000001, 10'b0000000010, 10'b0000000100, 10'b0000001000,
    //   10'b0000010000, 10'b0000100000, 10'b0001000000, 10'b0010000000,
    //   10'b0100000000, 10'b1000000000)
    reg [9:0] next_state; // Internal next-state register

    // State register (positive-edge triggered, starts in 'S' at reset)
    // The specification says: "At reset, the state machine starts in state 'S'."
    // We model the combinational next-state logic; reset initialization to S
    // is typically handled by the synthesis tool or an initial block not shown
    // here, as no reset port is listed in the module ports.
    always @(posedge clk) begin
        // Note: In a complete design, a reset mechanism would be added.
        // Here we simply update next_state on the clock edge.
        // The initial value should be 10'b0000000001 (S state) for proper reset behavior.
        next_state <= next_state; // Placeholder: actual reset handling depends on tool
    end

    // Combinational next-state logic (derived by inspection of the state diagram)
    // Note: The 'state' input port is provided per specification but the
    // state machine transitions are driven by the internal next_state register
    // and the inputs (d, done_counting, ack). The following case statement
    // uses the internal register state for transition derivation.
    always @(*) begin
        // Default: stay in current state
        next_state = state; // Latches current state input for default case

        case (state)
            // S state:  10'b0000000001
            10'b0000000001: begin
                if (d == 1'b0)
                    next_state = 10'b0000000001; // S --d=0--> S
                else
                    next_state = 10'b0000000010; // S --d=1--> S1
            end

            // S1 state: 10'b0000000010
            10'b0000000010: begin
                if (d == 1'b0)
                    next_state = 10'b0000000001; // S1 --d=0--> S
                else
                    next_state = 10'b0000001000; // S1 --d=1--> S11
            end

            // S11 state: 10'b0000001000
            10'b0000001000: begin
                if (d == 1'b0)
                    next_state = 10'b0000000100; // S11 --d=0--> S110
                else
                    next_state = 10'b0000001000; // S11 --d=1--> S11
            end

            // S110 state: 10'b0000000100
            10'b0000000100: begin
                if (d == 1'b0)
                    next_state = 10'b0000000001; // S110 --d=0--> S
                else
                    next_state = 10'b0000100000; // S110 --d=1--> B0
            end

            // B0 state: 10'b0000010000
            10'b0000010000: begin
                // B0 --(always go to next cycle)--> B1
                next_state = 10'b0000100000;
            end

            // B1 state: 10'b0000100000
            10'b0000100000: begin
                // B1 --(always go to next cycle)--> B2
                next_state = 10'b0001000000;
            end

            // B2 state: 10'b0001000000
            10'b0001000000: begin
                // B2 --(always go to next cycle)--> B3
                next_state = 10'b0010000000;
            end

            // B3 state: 10'b0010000000
            10'b0010000000: begin
                // B3 --(always go to next cycle)--> Count
                next_state = 10'b0100000000;
            end

            // Count state: 10'b0100000000
            10'b0100000000: begin
                if (done_counting == 1'b0)
                    next_state = 10'b0100000000; // Count --done_counting=0--> Count
                else
                    next_state = 10'b1000000000; // Count --done_counting=1--> Wait
            end

            // Wait state: 10'b1000000000
            10'b1000000000: begin
                if (ack == 1'b0)
                    next_state = 10'b1000000000; // Wait --ack=0--> Wait
                else
                    next_state = 10'b0000000001; // Wait --ack=1--> S
            end

            default: begin
                // Should never happen with one-hot encoding, but reset to S
                next_state = 10'b0000000001;
            end
        endcase
    end

    // Combinational output logic (derived by inspection of the output table)
    // done, counting, shift_ena are Moore outputs (depend only on the internal state register)

    // done: Asserted in Wait state
    assign done = (next_state == 10'b1000000000) ? 1'b1 : 1'b0;

    // counting: Asserted in Count state
    assign counting = (next_state == 10'b0100000000) ? 1'b1 : 1'b0;

    // shift_ena: Asserted in B0, B1, B2, B3 states
    assign shift_ena = (next_state == 10'b0000010000 || next_state == 10'b0000100000 ||
                        next_state == 10'b0001000000 || next_state == 10'b0010000000) ? 1'b1 : 1'b0;

    // Next-state assertion outputs (one-hot indicators for the next state)
    // B3_next: Assert when next-state is B3
    assign B3_next = (next_state == 10'b0010000000) ? 1'b1 : 1'b0;

    // S_next: Assert when next-state is S
    assign S_next = (next_state == 10'b0000000001) ? 1'b1 : 1'b0;

    // S1_next: Assert when next-state is S1
    assign S1_next = (next_state == 10'b0000000010) ? 1'b1 : 1'b0;

    // Count_next: Assert when next-state is Count
    assign Count_next = (next_state == 10'b0100000000) ? 1'b1 : 1'b0;

    // Wait_next: Assert when next-state is Wait
    assign Wait_next = (next_state == 10'b1000000000) ? 1'b1 : 1'b0;

endmodule
